import { AddScheduledMaintenanceExternalCalendars1805000000000 } from "../../../../Server/Infrastructure/Postgres/SchemaMigrations/1805000000000-AddScheduledMaintenanceExternalCalendars";
import SchemaMigrations from "../../../../Server/Infrastructure/Postgres/SchemaMigrations/Index";
import { MigrationInterface, QueryRunner } from "typeorm";
import fs from "fs";
import path from "path";
import { beforeAll, describe, expect, test } from "@jest/globals";

/*
 * The migration was generated by TypeORM against a fully migrated throwaway
 * database; what is pinned is what it must hold: the two new tables and
 * nothing else (a generator pointed at a drifted database emits changes to
 * unrelated tables), the columns the services write, the indexes the
 * Workers' job and the calendar page read by, rows that go with their
 * project - and events with their calendar - and a down() that undoes all
 * of it.
 */

const MIGRATION_NAME: string =
  "AddScheduledMaintenanceExternalCalendars1805000000000";
const TIMESTAMP: number = 1805000000000;
const CALENDARS: string = "ScheduledMaintenanceExternalCalendar";
const EVENTS: string = "ScheduledMaintenanceExternalCalendarEvent";

const CREATE_TABLE_PATTERN: RegExp = /^CREATE TABLE "([A-Za-z]+)"/;
const INDEX_NAME_PATTERN: RegExp = /CREATE (?:UNIQUE )?INDEX "([^"]+)"/;
const TABLE_MENTION_PATTERN: RegExp = /(?:TABLE|ON|REFERENCES) "([A-Za-z]+)"/g;
const TRAILING_TIMESTAMP_PATTERN: RegExp = /(\d+)$/;

type MigrationClass = new () => MigrationInterface;

async function run(direction: "up" | "down"): Promise<Array<string>> {
  const queries: Array<string> = [];

  const runner: QueryRunner = {
    query: async (sql: string): Promise<void> => {
      queries.push(sql);
    },
  } as unknown as QueryRunner;

  const migration: AddScheduledMaintenanceExternalCalendars1805000000000 =
    new AddScheduledMaintenanceExternalCalendars1805000000000();

  if (direction === "up") {
    await migration.up(runner);
  } else {
    await migration.down(runner);
  }

  return queries;
}

let up: Array<string> = [];
let down: Array<string> = [];

beforeAll(async () => {
  up = await run("up");
  down = await run("down");
});

function createTable(table: string): string {
  const statement: string | undefined = up.find((sql: string) => {
    return sql.startsWith(`CREATE TABLE "${table}" (`);
  });

  if (!statement) {
    throw new Error(`No CREATE TABLE for ${table}`);
  }

  return statement;
}

describe("AddScheduledMaintenanceExternalCalendars migration", () => {
  test("names itself after its timestamp", () => {
    expect(AddScheduledMaintenanceExternalCalendars1805000000000.name).toBe(
      MIGRATION_NAME,
    );
    expect(
      new AddScheduledMaintenanceExternalCalendars1805000000000().name,
    ).toBe(MIGRATION_NAME);
  });

  test("is registered exactly once, after every migration older than it", () => {
    const registered: Array<MigrationClass> =
      SchemaMigrations as Array<MigrationClass>;

    expect(
      registered.filter((migration: MigrationClass) => {
        return (
          migration === AddScheduledMaintenanceExternalCalendars1805000000000
        );
      }),
    ).toHaveLength(1);

    const index: number = registered.indexOf(
      AddScheduledMaintenanceExternalCalendars1805000000000,
    );

    for (let before: number = 0; before < index; before++) {
      const match: RegExpMatchArray | null = registered[before]!.name.match(
        TRAILING_TIMESTAMP_PATTERN,
      );

      expect(match ? parseInt(match[1]!, 10) : 0).toBeLessThan(TIMESTAMP);
    }
  });

  test("is backed by exactly one file carrying its timestamp", () => {
    const directory: string = path.join(
      __dirname,
      "../../../../Server/Infrastructure/Postgres/SchemaMigrations",
    );

    expect(
      fs.readdirSync(directory).filter((file: string) => {
        return file.startsWith(`${TIMESTAMP}-`);
      }),
    ).toEqual([`${TIMESTAMP}-AddScheduledMaintenanceExternalCalendars.ts`]);
  });

  test("creates the two new tables and touches nothing but them, their project and their users", () => {
    const created: Array<string> = up
      .map((sql: string) => {
        return sql.match(CREATE_TABLE_PATTERN)?.[1] || null;
      })
      .filter((name: string | null): name is string => {
        return name !== null;
      });

    expect(created).toEqual([CALENDARS, EVENTS]);

    const mentioned: Set<string> = new Set<string>();

    for (const sql of [...up, ...down]) {
      for (const match of sql.matchAll(TABLE_MENTION_PATTERN)) {
        mentioned.add(match[1]!);
      }
    }

    expect([...mentioned].sort()).toEqual(
      [CALENDARS, EVENTS, "Project", "User"].sort(),
    );
  });

  test("a calendar holds its settings, its link as text, and what its last read found", () => {
    const statement: string = createTable(CALENDARS);

    for (const column of [
      '"projectId" uuid NOT NULL',
      '"name" character varying(100) NOT NULL',
      '"calendarUrl" text NOT NULL',
      '"calendarHost" character varying(100)',
      '"color" character varying(10) NOT NULL',
      '"isEnabled" boolean NOT NULL DEFAULT true',
      `"refreshIntervalInMinutes" integer NOT NULL DEFAULT '60'`,
      '"lastReadAt" TIMESTAMP WITH TIME ZONE',
      '"lastReadAttemptAt" TIMESTAMP WITH TIME ZONE',
      '"lastReadError" character varying(100)',
      '"lastReadHttpStatus" integer',
      `"eventCount" integer NOT NULL DEFAULT '0'`,
      '"hasMoreEvents" boolean NOT NULL DEFAULT false',
      '"nextReadAt" TIMESTAMP WITH TIME ZONE',
      '"contentDigest" character varying(100)',
    ]) {
      expect(statement).toContain(column);
    }
  });

  test("an event holds a title, its times and whether it is all day", () => {
    const statement: string = createTable(EVENTS);

    for (const column of [
      '"projectId" uuid NOT NULL',
      '"scheduledMaintenanceExternalCalendarId" uuid NOT NULL',
      '"title" character varying(500)',
      '"startsAt" TIMESTAMP WITH TIME ZONE NOT NULL',
      '"endsAt" TIMESTAMP WITH TIME ZONE NOT NULL',
      '"isAllDay" boolean NOT NULL DEFAULT false',
      '"version" integer NOT NULL',
    ]) {
      expect(statement).toContain(column);
    }
  });

  test("the due calendars and a period's events are found by index", () => {
    const indexOn: (table: string, columns: string) => boolean = (
      table: string,
      columns: string,
    ): boolean => {
      return up.some((sql: string) => {
        return (
          sql.startsWith('CREATE INDEX "IDX_') &&
          sql.endsWith(`" ON "${table}" (${columns}) `)
        );
      });
    };

    expect(indexOn(CALENDARS, '"nextReadAt"')).toBe(true);
    expect(indexOn(CALENDARS, '"isEnabled"')).toBe(true);
    expect(
      indexOn(EVENTS, '"scheduledMaintenanceExternalCalendarId", "startsAt"'),
    ).toBe(true);
  });

  test("calendars and events go with their project, events with their calendar; a user's removal leaves them", () => {
    expect(up).toContainEqual(
      expect.stringContaining(
        `ALTER TABLE "${CALENDARS}" ADD CONSTRAINT`,
      ),
    );
    expect(
      up.filter((sql: string) => {
        return sql.includes(
          'FOREIGN KEY ("projectId") REFERENCES "Project"("_id") ON DELETE CASCADE',
        );
      }),
    ).toHaveLength(2);
    expect(up).toContainEqual(
      expect.stringContaining(
        `FOREIGN KEY ("scheduledMaintenanceExternalCalendarId") REFERENCES "${CALENDARS}"("_id") ON DELETE CASCADE`,
      ),
    );
    expect(up).toContainEqual(
      expect.stringContaining(
        'FOREIGN KEY ("createdByUserId") REFERENCES "User"("_id") ON DELETE SET NULL',
      ),
    );
  });

  test("down() drops every index up() created, the events before the calendars", () => {
    const created: Array<string> = up
      .map((sql: string) => {
        return sql.match(INDEX_NAME_PATTERN)?.[1] || null;
      })
      .filter((name: string | null): name is string => {
        return name !== null;
      });

    expect(created).toHaveLength(6);

    for (const name of created) {
      expect(down).toContain(`DROP INDEX "public"."${name}"`);
    }

    expect(down.indexOf(`DROP TABLE "${EVENTS}"`)).toBeLessThan(
      down.indexOf(`DROP TABLE "${CALENDARS}"`),
    );
    expect(down[down.length - 1]).toBe(`DROP TABLE "${CALENDARS}"`);
  });
});
